<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Index/account')}" >账号列表</a>|					<a href="javascript:void(0);"  onclick="window.o2oTop.artiframe('{pigcms{:U('Index/admin',array('area_id'=>$_GET['area_id']))}','添加管理账号',500,450,true,false,false,addbtn,'add',true);">添加管理员</a>|					<a href="{pigcms{:U('Index/authority_group')}" >权限套餐</a>					<if condition="$config.open_juhepay eq 1">|<a href="{pigcms{:U('Index/salesman_list')}" class="on">业务员流水</a></if>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('Index/salesman_list')}" method="get">							<input type="hidden" name="c" value="Index"/>												<input type="hidden" name="a" value="salesman_list"/>														<div id="choose_pca" province_idss="<if condition="$_GET['province_idss'] neq ''">{pigcms{$_GET.province_idss}<elseif condition="$_GET['pid']" />{pigcms{$_GET.pid}</if>" <if condition="$_GET['type'] eq 2 AND isset($_GET['type'])">city_idss="{pigcms{$_GET.city_idss}"</if>  style="display:inline"></div>							<!--input type="hidden" name="area_type" value="{pigcms{$_GET['type']}"/>							<input type="hidden" name="pid" value="{pigcms{$_GET['pid']}"/-->							<input type="hidden" name="is_city" value="<if condition="$_GET['type'] eq 2 AND isset($_GET['type'])">1<else />0</if>"/>							<input type="submit" style="margin-right:20px;" value="查询" class="button"/>						商家流水总额：{pigcms{$all_money|floatval}{pigcms{$config['Currency_txt']}							<a  href="javascript:void(0)" onclick="exports()" class="button" style="margin-right: 10px;">导出</a>						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th><a href="{pigcms{:U('User/index',array('sort'=>'uid'))}" style="color:blue;">ID</a></th>								<th>管理员名称</th>								<th>{pigcms{$now_type_str}</th>								<th class="textcenter">商家流水总额</th>								<th class="textcenter">操作</th>														</tr>						</thead>						<tbody>							<if condition="is_array($area_list)">								<volist name="area_list" id="vo">										<php>if($vo['spread_count']==0){ continue; }</php>									<tr>										<td>{pigcms{$vo.area_id}</td>																		<td>{pigcms{$vo.admin_name}</td>										<td>{pigcms{$vo.area_name}</td>										<td class="textcenter">{pigcms{$config['Currency_symbol']}{pigcms{$vo.spread_money|floatval=###}</td>										<td class="textcenter">										共{pigcms{$vo.spread_count|intval}个业务员 &nbsp;&nbsp;&nbsp;										<if condition="$_GET['type'] eq 2">										<a href="{pigcms{:U('Index/admin_money_list')}&pid={pigcms{$vo.area_id}&type={pigcms{$vo['area_type']}" >查看下级</a>										<else />										<a href="{pigcms{:U('Index/salesman_list')}&pid={pigcms{$vo.area_id}&type={pigcms{$vo['area_type']+1}" >查看下级</a>										</if>																				</td>																			</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="5">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="5">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>		<if condition="$_GET['type'] neq 2">		<style>						#choose_cityss{				display:none;			}			</style>		</if>		<script>		 var url = "{pigcms{$config.site_url}"		 var export_url = "{pigcms{:U('Index/salesman_list_export')}"	<if condition="!isset($_GET['type'])">		$('#choose_cityss').hide();	</if></script><if condition="$system_session['area_type'] lt 3 "><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script></if><script>	</script><script type="text/javascript" src="{pigcms{$static_public}